def parse_memory_refine_agent_response(text: str) -> Dict[str, object]:
    cleaned = str(text or "").strip()
    if cleaned.startswith("```"):
        cleaned = re.sub(r"^```(?:json)?\s*", "", cleaned)
        cleaned = re.sub(r"\s*```$", "", cleaned)
    payload = json.loads(cleaned or "{}")
    action = str(payload.get("action", "skip") or "skip").strip().lower()
    if action not in {"split", "checked", "skip"}:
        action = "skip"
    items: List[Dict[str, object]] = []
    raw_items = payload.get("items")
    if isinstance(raw_items, list):
        for raw in raw_items:
            if not isinstance(raw, dict):
                continue
            memory_text = clean_search_text(str(raw.get("memory", "") or ""), 900)
            if not memory_text:
                continue
            try:
                confidence = float(raw.get("confidence", 0.7))
            except Exception:
                confidence = 0.7
            items.append(
                {
                    "label": normalize_memory_label(raw.get("label", "other")),
                    "memory": memory_text,
                    "timeline_at": str(raw.get("timeline_at", "") or "").strip(),
                    "timeline_start_at": str(raw.get("timeline_start_at", "") or "").strip(),
                    "timeline_end_at": str(raw.get("timeline_end_at", "") or "").strip(),
                    "timeline_kind": normalize_timeline_kind(raw.get("timeline_kind", "")),
                    "confidence": min(1.0, max(0.0, confidence)),
                }
            )
    return {
        "action": action,
        "rationale": clean_search_text(str(payload.get("rationale", "") or ""), 500),
        "items": items,
    }


