def mark_curated_memory_refined(memory_id: int, status: str, reason: str = "") -> bool:
    normalized = status.strip()[:40]
    with connect_db() as conn:
        cur = conn.execute(
            """
            UPDATE curated_memories
            SET refine_status = ?,
                refined_at = ?,
                refine_reason = ?,
                updated_at = ?
            WHERE id = ?
            """,
            (normalized, utc_now(), reason[:800], utc_now(), int(memory_id)),
        )
    return cur.rowcount > 0


